from pathlib import Path
import json, html, re

ROOT = Path(__file__).resolve().parents[1]
D = ROOT / 'public'
catalog = json.loads((ROOT/'data/catalog.json').read_text())
esc = html.escape
SPOT = 'https://open.spotify.com/artist/04HZ4GubB66CqMpJrHysy3'
APPLE = 'https://music.apple.com/us/artist/mr-blindbandit/1622341304'
own = sorted([r for r in catalog if r['artist']=='Mr. Blindbandit'], key=lambda r:r['release_date'], reverse=True)
mask = [r for r in catalog if 'Maskman' in r['artist']]
nav = [('Music','/music/'),('Label','/label/'),('Submit','/submit/'),('Community','/community/'),('Explore','/explore/'),('Join','/signup/'),('Support','/support/')]

def button(label,url): return f'<a class="button" href="{esc(url)}">{label} <span aria-hidden="true">↗</span></a>'
def intro(kicker,title,description): return f'<section class="page-intro shell"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lede">{description}</p></section>'
def cards(records):
    out=''
    for r in records:
        title=re.sub(r' - (Single|EP)$','',r['title'])
        out+=f'''<article class="record" data-title="{esc(r['title'].lower())}" data-type="{r['type']}" data-year="{r['year']}"><a class="cover" href="{esc(r['url'])}" aria-label="Listen to {esc(title)} on Apple Music"><img src="/assets/releases/{r['id']}.jpg" alt="{esc(title)} cover artwork" width="500" height="500" loading="lazy"><span class="play-badge" aria-hidden="true">↗</span></a><p class="eyebrow">{r['type']} / {r['year']}</p><h3>{esc(title)}</h3><p class="small">{esc(r['artist'])}</p><a class="record-link" href="{esc(r['url'])}">Listen on Apple Music ↗</a><button class="preview-link" data-apple="{esc(r['url'])}" data-name="{esc(title)}">Open player</button></article>'''
    return out
def player(kind,id,title):
    return f'<div class="player" data-player="{kind}" data-media="{id}"><div class="equalizer" aria-hidden="true">'+''.join('<i></i>' for _ in range(16))+f'</div><p class="eyebrow">{title}</p><button class="button load-player">Load {kind} player ▶</button><p class="small">Player loads when selected.</p></div>'
def heading(k,t,link='',label='Explore more'): return f'<div class="section-heading"><div><p class="eyebrow">{k}</p><h2>{t}</h2></div>'+ (f'<a class="text-link" href="{link}">{label} ↗</a>' if link else '')+'</div>'
def ticker(): return '<div class="ticker" aria-label="Ambient, cinematic, electronic, hip-hop"><div>'+''.join('<span'+(' aria-hidden="true"' if i else '')+'>AMBIENT <b>✳</b> CINEMATIC <b>✳</b> ELECTRONIC <b>✳</b> HIP-HOP <b>✳</b> </span>' for i in range(4))+'</div></div>'
def layout(route,title,description,body):
    links=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==route else '')+f'>{name}</a>' for name,url in nav)
    markup=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111310"><title>{title} — Mr. Blind Bandit</title><meta name="description" content="{esc(description)}"><meta property="og:title" content="{esc(title)} — Mr. Blind Bandit"><meta property="og:description" content="{esc(description)}"><meta property="og:image" content="https://mrblindbandit.net/assets/artist.jpg"><meta property="og:type" content="website"><link rel="canonical" href="https://mrblindbandit.net{route}"><link rel="icon" href="/assets/favicon.svg"><link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><div class="ambient" aria-hidden="true"></div><div class="scroll-progress" aria-hidden="true"></div><header><div class="header-inner"><a class="wordmark" href="/" aria-label="Mr. Blind Bandit home">MR. BLIND<span>BANDIT<b>.</b></span></a><button class="menu" aria-controls="navigation" aria-expanded="false" hidden>Menu +</button><nav id="navigation" aria-label="Main navigation">{links}</nav><a class="listen-top" href="{SPOT}">Listen ↗</a></div></header><main id="main">{body}</main><section class="closing shell"><p class="eyebrow">Keep the connection.</p><a href="/connect/">LET’S MAKE<br><span>SOMETHING.</span> ↗</a></section><footer class="shell"><div><a class="wordmark" href="/">MR. BLIND<span>BANDIT.</span></a><p>Blind-owned. Creator-driven.<br>Limitless vision.</p></div><div class="footer-links">{links}<a href="/press/">Press &amp; booking</a><a href="/connect/">Contact</a><a href="/privacy/">Privacy</a></div><div><button class="motion-toggle" aria-pressed="false" hidden>Pause motion</button><p>© 2026 Mr. Blindbandit.<br>All rights reserved.</p><a href="#main">Back to top ↑</a></div></footer><dialog id="music-dialog"><div class="dialog-heading"><h2 id="player-title">Listen</h2><button class="close-dialog" aria-label="Close music player">Close ×</button></div><div id="dialog-player"></div><p class="small">Playback and availability are provided by Apple Music.</p></dialog></body></html>'''
    path=D/route.strip('/')/'index.html' if route!='/' else D/'index.html'
    path.parent.mkdir(parents=True,exist_ok=True); path.write_text(markup)

home='''<section class="hero shell"><div class="hero-copy"><p class="eyebrow"><span class="live-dot"></span> Independent artist / Blindbandit Records</p><h1>MR. BLIND<br><span>BANDIT.</span></h1><p class="hero-tagline">A world you can feel.</p><p class="lede">Ambient worlds. Cinematic sound. A life without limits on imagination.</p><div class="actions">'''+button('Explore the music','/music/')+'''<a class="text-link" href="/story/">Meet the artist ↗</a></div><p class="coordinates">VIRGINIA ROOTS. &nbsp; PHILIPPINES HOME. &nbsp; WORLDWIDE SOUND.</p></div><figure class="portrait"><img src="/assets/artist.jpg" alt="Mr. Blindbandit in the Philippines, wearing a green shirt" width="531" height="640" fetchpriority="high"><figcaption>01 / THE ARTIST <span>MR. BLINDBANDIT</span></figcaption><div class="orbit" aria-hidden="true">INDEPENDENT<br>BY DESIGN ✳</div></figure></section>'''+ticker()
home+='<section class="shell section">'+heading('01 / Discover the catalog','SOUND WITHOUT<br>BORDERS.','/music/','All releases')+'<div class="records">'+cards(own[:4])+'</div></section>'
home+='''<section class="feature shell"><div class="feature-art"><img src="/assets/releases/6802446802.jpg" alt="DA BLINDBANDIT single artwork" width="500" height="500" loading="lazy"></div><div><p class="eyebrow">02 / The connection</p><h2>DA<br><span>BLINDBANDIT.</span></h2><p class="lede">UUu Tang Maskman × Mr. Blindbandit</p><p>A shared release. Two creative worlds. Meet the artists connected to the music, then explore their sounds.</p><div class="actions">'''+button('Play the collaboration','https://open.spotify.com/track/3dqbgoiAIj1baNpgCjTEjj')+'''<a class="text-link" href="/collaborators/">Artists I’ve worked with ↗</a></div></div></section>'''
home+='<section class="shell section">'+heading('03 / Find your way in','PICK YOUR<br>PORTAL.')+'''<div class="portal-grid"><a href="/music/"><span>01 / LISTEN</span><h3>The discography</h3><p>Albums, EPs, singles, and alternate versions.</p><b>↗</b></a><a href="/story/"><span>02 / DISCOVER</span><h3>Behind the sound</h3><p>Kaeleb Heck. Virginia to the Philippines. A life built around creating.</p><b>↗</b></a><a href="/videos/"><span>03 / WATCH</span><h3>Beyond the studio</h3><p>Music, videos, and the person behind them.</p><b>↗</b></a></div></section>'''
home+='<section class="shell listen-section"><div><p class="eyebrow">Stay a little longer</p><h2>FIND YOUR<br>NEXT REPEAT.</h2><p>Press play and follow wherever the sound takes you.</p>'+button('Follow on Spotify',SPOT)+'</div>'+player('Spotify','04HZ4GubB66CqMpJrHysy3','MR. BLINDBANDIT / ARTIST RADIO')+'</section>'
layout('/','Official artist website','Explore the music, collaborators, videos and story of Mr. Blindbandit, an independent artist based in the Philippines.',home)

music=intro('THE DISCOGRAPHY','ENTER THE<br><span>SOUNDSCAPE.</span>','Albums, singles, dreamscapes, and alternate versions. Find a familiar favorite or follow a sound somewhere new.')
music+='<section class="shell catalog-section"><div class="filters" hidden><label>Search releases<input type="search" id="search" placeholder="Find a title…"></label><label>Format<select id="format"><option value="">All formats</option><option>Album</option><option>EP</option><option>Single</option></select></label><label>Year<select id="year-filter"><option value="">All years</option>'+''.join(f'<option>{y}</option>' for y in sorted({r['year'] for r in own},reverse=True))+'</select></label><button id="reset-filters">Reset</button></div><p id="result-count" class="small" role="status">'+str(len(own))+' releases</p><div class="records catalog">'+cards(own)+'</div><p id="empty-results" hidden>No releases match. Try another title or reset the filters.</p></section>'
music+='<section class="shell section">'+heading('Keep exploring','YOUR MUSIC.<br>YOUR PLATFORM.')+'<div class="actions">'+button('Spotify',SPOT)+button('Apple Music',APPLE)+button('YouTube','https://www.youtube.com/@MrBlindbandit')+'</div></section>'
